#include <stdio.h>
#include <string.h>
#include <math.h>

double prob[16][16];
double dp[1 << 16];
double cat_win_streak[16][17][17]; // cat i, start pos j, defeats exactly k enemies (k from 0 to remaining)

int main() {
    int m, n;
    scanf("%d %d", &m, &n);
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%lf", &prob[i][j]);
        }
    }

    // Precompute for each cat and start position probability of defeating exactly k consecutive
    for (int i = 0; i < m; i++) {
        for (int start = 0; start <= n; start++) {
            double product = 1.0;
            for (int k = 0; k <= n - start; k++) {
                if (k == 0) {
                    cat_win_streak[i][start][k] = 1.0 - prob[i][start]; // fails immediately
                } else {
                    product *= prob[i][start + k - 1];
                    double lose_prob = (start + k < n) ? (1.0 - prob[i][start + k]) : 0.0;
                    if (start + k == n) {
                        cat_win_streak[i][start][k] = product; // defeats all remaining
                    } else {
                        cat_win_streak[i][start][k] = product * lose_prob;
                    }
                }
            }
        }
    }

    int total_states = 1 << n;
    for (int mask = 0; mask < total_states; mask++) {
        dp[mask] = 0.0;
    }
    dp[0] = 1.0;

    for (int mask = 0; mask < total_states; mask++) {
        if (dp[mask] == 0.0) continue;
        int start = __builtin_popcount(mask); // next enemy index
        if (start == n) continue;
        for (int cat = 0; cat < m; cat++) {
            // try sending cat
            for (int k = 0; k <= n - start; k++) {
                double p = cat_win_streak[cat][start][k];
                if (p == 0.0) continue;
                int new_mask = mask;
                for (int t = 0; t < k; t++) {
                    new_mask |= (1 << (start + t));
                }
                double new_val = dp[mask] * p;
                if (new_val > dp[new_mask]) {
                    dp[new_mask] = new_val;
                }
            }
        }
    }

    printf("%.15lf\n", dp[total_states - 1]);
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <math.h>

int m, n;
double p[16][16];
double dp[17][1<<16];
int computed[17][1<<16];

double solve(int r, int S) {
    if (r == n) return 1.0;
    if (S == 0) return 0.0;
    if (computed[r][S]) return dp[r][S];
    computed[r][S] = 1;

    double best = 0.0;
    for (int i = 0; i < m; i++) {
        if (!(S & (1<<i))) continue;
        int newS = S ^ (1<<i);
        // cat i starts at room r
        double prob_reach = 1.0; // probability cat i reaches room k
        double val = 0.0;
        for (int k = r; k < n; k++) {
            // cat gets defeated at room k: prob_reach * (1 - p[i][k])
            double die_prob = prob_reach * (1.0 - p[i][k]);
            val += die_prob * solve(k, newS);
            prob_reach *= p[i][k];
        }
        // cat clears all remaining rooms
        val += prob_reach * 1.0;
        if (val > best) best = val;
    }
    dp[r][S] = best;
    return best;
}

