#include <stdio.h>
#include <stdlib.h>

#define MAXM 16
#define MAXN 16

double p[MAXM][MAXN];
double survive[MAXM][MAXN + 1];   // survive[i][k] = product of p[i][k..n-1], survive[i][n]=1
double dp[1 << MAXM][MAXN + 1];   // dp[mask][r] = max probability to clear rooms r..n-1 with unused cats in mask

static inline double maxd(double a, double b) {
    return a > b ? a : b;
}

int main(void) {
    int m, n;
    if (scanf("%d %d", &m, &n) != 2) return 0;

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            scanf("%lf", &p[i][j]);
        }
    }

    for (int i = 0; i < m; ++i) {
        survive[i][n] = 1.0;
        for (int j = n - 1; j >= 0; --j) {
            survive[i][j] = survive[i][j + 1] * p[i][j];
        }
    }

    int total_masks = 1 << m;

    for (int mask = 0; mask < total_masks; ++mask) dp[mask][n] = 1.0;

    for (int r = n - 1; r >= 0; --r) {
        for (int mask = 0; mask < total_masks; ++mask) {
            double best = 0.0;

            for (int i = 0; i < m; ++i) {
                if (!(mask & (1 << i))) continue;

                double cur = 0.0;
                double pref = 1.0;

                // Cat i fails at room t (r <= t < n)
                for (int t = r; t < n; ++t) {
                    cur += pref * (1.0 - p[i][t]) * dp[mask ^ (1 << i)][t];
                    pref *= p[i][t];
                }

                // Cat i clears all remaining rooms
                cur += pref; // dp[...][n] = 1

                best = maxd(best, cur);
            }

            dp[mask][r] = best;
        }
    }

    printf("%.12f\n", dp[total_masks - 1][0]);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m, n;
    cin >> m >> n;
    vector<vector<double>> prob(m, vector<double>(n));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            cin >> prob[i][j];
        }
    }

    // precompute for each cat and each starting position 'start',
    // the probability that it defeats enemies from start to end-1 and loses at end.
    // Also the probability it defeats all from start to n-1.
    // We'll store for each cat and each start: vector<double> of size n-start+1,
    // where index k means it clears exactly start..start+k-1 and loses at start+k.
    // Last index means clears all remaining.

    vector<vector<vector<double>>> catProbs(m, vector<vector<double>>(n));
    for (int c = 0; c < m; c++) {
        for (int start = 0; start < n; start++) {
            vector<double> probs(n - start + 1, 0.0);
            double p = 1.0; // probability of surviving so far
            for (int k = 0; k <= n - start; k++) {
                if (k == n - start) {
                    // defeats all from start to end
                    probs[k] = p;
                } else {
                    int room = start + k;
                    // defeats this room then loses at next
                    double loseHere = p * (1.0 - prob[c][room]);
                    probs[k] = loseHere;
                    p *= prob[c][room];
                }
            }
            catProbs[c][start] = probs;
        }
    }

    int totalMasks = 1 << n;
    vector<double> dp(totalMasks, 0.0);
    dp[0] = 1.0;

    for (int mask = 0; mask < totalMasks; mask++) {
        if (dp[mask] == 0.0) continue;
        // find first room not cleared
        int start = __builtin_ctz(~mask & ((1 << n) - 1));
        if (start >= n) continue; // all cleared

        for (int c = 0; c < m; c++) {
            // if cat c already used? We can reuse cats, so no restriction.
            const auto &probs = catProbs[c][start];
            for (int k = 0; k < (int)probs.size(); k++) {
                int cleared = start + k;
                int newMask = mask;
                for (int r = start; r < cleared; r++) {
                    newMask |= (1 << r);
                }
                dp[newMask] = max(dp[newMask], dp[mask] * probs[k]);
            }
        }
    }

    cout << fixed << setprecision(12) << dp[totalMasks - 1] << "\n";
    return 0;
}

