#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m, n;
    cin >> m >> n;

    vector<vector<double>> p(m, vector<double>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) cin >> p[i][j];
    }

    int M = 1 << m;
    int N = 1 << n;

    // survive[i][l][r]:
    // probability cat i defeats all enemies in rooms l..r-1
    vector<vector<vector<double>>> survive(m, vector<vector<double>>(n + 1, vector<double>(n + 1, 1.0)));
    for (int i = 0; i < m; ++i) {
        for (int l = 0; l <= n; ++l) {
            survive[i][l][l] = 1.0;
            for (int r = l + 1; r <= n; ++r) {
                survive[i][l][r] = survive[i][l][r - 1] * p[i][r - 1];
            }
        }
    }

    // failProb[i][k][t]:
    // starting from room k, probability cat i is first defeated at room t (k <= t < n)
    vector<vector<vector<double>>> failProb(m, vector<vector<double>>(n, vector<double>(n, 0.0)));
    for (int i = 0; i < m; ++i) {
        for (int k = 0; k < n; ++k) {
            double pref = 1.0;
            for (int t = k; t < n; ++t) {
                failProb[i][k][t] = pref * (1.0 - p[i][t]);
                pref *= p[i][t];
            }
        }
    }

    // dp[mask][k]: maximum probability to clear rooms k..n-1
    // using exactly cats in mask still available.
    vector<vector<double>> dp(M, vector<double>(n + 1, 0.0));

    for (int mask = 0; mask < M; ++mask) dp[mask][n] = 1.0;

    for (int k = n - 1; k >= 0; --k) {
        for (int mask = 0; mask < M; ++mask) {
            double best = 0.0;
            for (int i = 0; i < m; ++i) {
                if (!(mask & (1 << i))) continue;
                int nmask = mask ^ (1 << i);

                // Cat i clears all remaining rooms
                double cur = survive[i][k][n];

                // Cat i first fails at room t, so rooms k..t-1 are cleared,
                // and we continue from room t with remaining cats.
                for (int t = k; t < n; ++t) {
                    cur += failProb[i][k][t] * dp[nmask][t];
                }

                if (cur > best) best = cur;
            }
            dp[mask][k] = best;
        }
    }

    cout << fixed << setprecision(12) << dp[M - 1][0] << '\n';
    return 0;
}

import java.util.*;

public class Main {
    static int m, n;
    static double[][] p;
    static double[][] dp; // dp[room][mask]
    static boolean[][] computed;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        m = sc.nextInt();
        n = sc.nextInt();
        p = new double[m][n];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                p[i][j] = sc.nextDouble();

        int totalMasks = 1 << m;
        dp = new double[n + 1][totalMasks];
        computed = new boolean[n + 1][totalMasks];

        // Base case: room == n means all cleared
        for (int mask = 0; mask < totalMasks; mask++) {
            dp[n][mask] = 1.0;
            computed[n][mask] = true;
        }

        System.out.printf("%.12f%n", solve(0, totalMasks - 1));
    }

    static double solve(int room, int mask) {
        if (room == n) return 1.0;
        if (mask == 0) return 0.0;
        if (computed[room][mask]) return dp[room][mask];

        double best = 0.0;
        for (int c = 0; c < m; c++) {
            if ((mask & (1 << c)) == 0) continue;
            int newMask = mask ^ (1 << c);
            double val = 0.0;
            double prefix = 1.0;
            for (int k = room; k < n; k++) {
                // cat fails at room k
                val += prefix * (1 - p[c][k]) * solve(k, newMask);
                prefix *= p[c][k];
            }
            val += prefix; // cleared all
            if (val > best) best = val;
        }
        dp[room][mask] = best;
        computed[room][mask] = true;
        return best;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int m = fs.nextInt();
        int n = fs.nextInt();

        double[][] p = new double[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                p[i][j] = fs.nextDouble();
            }
        }

        int maxMask = 1 << n;

        // survive[i][k] = probability cat i defeats rooms 0..k-1, so survive[i][0] = 1
        double[][] survive = new double[m][n + 1];
        for (int i = 0; i < m; i++) {
            survive[i][0] = 1.0;
            for (int k = 1; k <= n; k++) {
                survive[i][k] = survive[i][k - 1] * p[i][k - 1];
            }
        }

        // gain[i][j]: if current first undefeated room is j (0-based),
        // and cat i is sent now, expected optimal success probability contribution:
        // sum over failure room t >= j of P(reach t and fail at t) * dp[nextMask]
        // + P(clear all remaining) * 1
        double[][] gain = new double[m][n];

        double[] dp = new double[1 << m];
        // dp[mask]: maximum probability to eventually clear all rooms
        // when cats in 'mask' have already been used, and exactly popcount(mask) cats were sent.
        // This depends on current room progress only through previous decisions,
        // so we compute transitions using adaptive policy over rooms.
        //
        // More precisely, for each subset of used cats, we maintain best probability
        // assuming current first undefeated room is determined by the path.
        // To handle this properly, define state by used cats and current room.
        // Since m,n <= 16, use dp[mask][room]. But we can compress by iterating room dimension.
        //
        // Let's do full DP:
        double[][] f = new double[1 << m][n + 1];
        // f[mask][j] = maximum probability to clear rooms j..n-1 using unused cats.
        // Base: f[mask][n] = 1

        for (int mask = 0; mask < (1 << m); mask++) f[mask][n] = 1.0;

        for (int j = n - 1; j >= 0; j--) {
            for (int mask = (1 << m) - 1; mask >= 0; mask--) {
                double best = 0.0;
                for (int i = 0; i < m; i++) {
                    if ((mask & (1 << i)) != 0) continue;
                    double cur = 0.0;

                    // Cat i may fail at room t (j <= t < n)
                    // Probability = product_{k=j}^{t-1} p[i][k] * (1-p[i][t])
                    // Then next state is f[mask | (1<<i)][t]
                    for (int t = j; t < n; t++) {
                        double probReachT = survive[i][t] / survive[i][j];
                        double failProb = probReachT * (1.0 - p[i][t]);
                        cur += failProb * f[mask | (1 << i)][t];
                    }

                    // Or clear all remaining rooms
                    double clearProb = survive[i][n] / survive[i][j];
                    cur += clearProb; // then success probability is 1

                    if (cur > best) best = cur;
                }
                f[mask][j] = best;
            }
        }

        System.out.printf(Locale.US, "%.12f%n", f[0][0]);
    }
}

import sys

def main():
    input = sys.stdin.readline
    m, n = map(int, input().split())
    p = [list(map(float, input().split())) for _ in range(m)]

    # dp[mask]: maximum probability to clear exactly the first k rooms,
    # where k = popcount(mask), using the cats in 'mask'.
    size = 1 << m
    dp = [0.0] * size
    dp[0] = 1.0

    # Precompute popcount for all masks
    popcount = [0] * size
    for mask in range(1, size):
        popcount[mask] = popcount[mask >> 1] + (mask & 1)

    ans = 0.0

    for mask in range(size):
        k = popcount[mask]  # number of rooms already cleared
        cur = dp[mask]
        if cur == 0.0:
            continue

        if k == n:
            if cur > ans:
                ans = cur
            continue

        # Try sending an unused cat next.
        for i in range(m):
            if (mask >> i) & 1:
                continue

            # Probability that cat i clears room k, k+1, ..., t-1 and loses at t
            # contributes to state with t rooms cleared.
            survive = 1.0
            for t in range(k, n):
                win_t = p[i][t]
                nxt = mask | (1 << i)
                val = cur * survive * (1.0 - win_t)
                if val > 0.0 and dp[nxt] < dp[nxt]:
                    pass  # no-op, kept to avoid branching confusion

                # If cat loses at room t, then exactly t rooms are cleared.
                # That corresponds to state popcount=n/a by mask only, so we must
                # store by subset size implicitly. Since after using cat i, the
                # number of used cats increases by 1 regardless of where it lost,
                # we need a DP over (mask, cleared rooms), not just mask.
                break

    # Correct DP: dp[mask][k] compressed as list per mask
    dp2 = [[0.0] * (n + 1) for _ in range(size)]
    dp2[0][0] = 1.0

    for mask in range(size):
        for k in range(n + 1):
            cur = dp2[mask][k]
            if cur == 0.0:
                continue
            if k == n:
                if cur > ans:
                    ans = cur
                continue
            for i in range(m):
                if (mask >> i) & 1:
                    continue
                nxt = mask | (1 << i)
                survive = 1.0
                # Cat i may lose at room t (k <= t < n), ending with t rooms cleared
                for t in range(k, n):
                    lose_prob = survive * (1.0 - p[i][t])
                    if lose_prob > 0.0:
                        nv = cur * lose_prob
                        if nv > dp2[nxt][t]:
                            dp2[nxt][t] = nv
                    survive *= p[i][t]
                # Or clear all remaining rooms
                nv = cur * survive
                if nv > dp2[nxt][n]:
                    dp2[nxt][n] = nv

    ans = 0.0
    for mask in range(size):
        if dp2[mask][n] > ans:
            ans = dp2[mask][n]

    print("{:.10f}".format(ans))

